\label{lem:alpha_beta_x_no_func}
	Let $\mathcal{M}$ be a $d$-dimensional sub-manifold of $\mathbb{R}^D$ with reach $\tau$. For any $p \in \mathcal{M}$, let $T_{p}\mathcal{M}$ be the tangent of $\mathcal{M}$ at $p$ and let $ H\in Gr(d, D) $ such that $ \angle_{\max}(T_p\mathcal{M}, H) = \alpha\leq \pi/4 $.
	For any $x = p + x_H$, where $x_H\in H$,$\|x_H\|\leq c_{\pi/4}\tau$ for some constant $c_{\pi/4}$, and $y\in H^\perp$  such that $\|x-p\|\leq \tau \cos \alpha$, $\|y\| \leq \tau/2$ and $(x + y)\in \mathcal{M}$, we denote $ \beta = \angle_{\max}(T_{x+y}\mathcal{M}, H) $.
	Then, we get that
	\[
	\alpha - 2 \sqrt{ \frac{\norm{x_H}}{\tau}\lrbrackets{2 \alpha + \frac{\norm{x_H}}{\tau}} } 
	\leq \beta \leq
	\alpha + 2 \sqrt{ \frac{\norm{x_H}}{\tau}\lrbrackets{2 \alpha + \frac{\norm{x_H}}{\tau}} }
	\]

\label{cor:GraphOfFunctionTau_ROI}
Let the requirements of Lemma \ref{lem:M_is_locally_a_fuinction_clean}, and the sampling assumptions of Section \ref{sec:SamplingAssumptions} hold. Denote the projection of $r$ onto $\mathcal{M}$ by $p_r = P_{\mathcal{M}}(r)$, let $U_{\textrm{ROI}}$ be as defined in \eqref{eq:ROI_clean}. 
Then, any $r_i \in U_{\textrm{ROI}}$ can be written as
\begin{equation}\label{eq:FunctionGraph_pi_ei_clean}
r_i = \underbrace{p_r + (x_i, \phi_{p_r}(x_i))_{T_{p_r}\mathcal{M}}}_{p_i}+\varepsilon_i
,\end{equation}
where $x_i= P_{T_{p_r}\mathcal{M}}(r_i - p_r)$ and $\|\varepsilon_i\| \leq \sigma$.

It follows immediately from Lemma \ref{lem:f_bound_circle_clean} 
\begin{equation}\label{eq:eq:bound_phix_clean}
    \norm{\phi_p(x)}_{\mathbb{R}^{D-d}} \leq \tau - \sqrt{\tau^2 - \norm{x}_{\mathbb{R}^d}^2}
,\end{equation}
and using the triangle inequality we can say that
\begin{equation}\label{eq:bound_x_phix_clean}
    \norm{(x,\phi_p(x))}_{\mathbb{R}^{D}} \leq \norm{x}_{\mathbb{R}^d} + \tau - \sqrt{\tau^2 - \norm{x}_{\mathbb{R}^d}^2}
.\end{equation}

\label{lem:num_of_samples_in_a_ball_clean}
	Let $\mathcal{M}$ be a compact $d$-dimensional sub-manifold of $\mathbb{R}^D$ with reach $\tau$  bounded away from zero, and a Riemannian metric $G_p$ pronounced through the chart $\varphi_p$ around a point $ p\in \mathcal{M} $ \emphbrackets{see \eqref{eq:LocalChart_clean}}. 
    Let $\mathcal{M}_\sigma$ be a tubular neighborhood around $ \mathcal{M} $ of radius $ \sigma $ \emphbrackets{see \eqref{eq:Msigma}}, and assume $\sqrt{\frac{\sigma}{\tau}} < \frac{1}{2}$. 
    Suppose that $\mu$ is the uniform distribution on $ \mathcal{M}_\sigma $. 
    Let $X = \{r_1, \ldots,r_n\}$ be $n$ points sampled i.i.d from $\mu$, and denote the volume of a $d$-dimensional unit ball by  $ \mathrm{V}_d = \frac{\pi^{d/2}}{\Gamma(d/2+1)} $.
    Denote,
    \begin{align}
    \label{eq:mu_min_max_def}
    \begin{split}
