\begin{equation*}
\|I_d-J_{\wtilde{x}_\theta}[0]\| = \mathcal{O}(\frac{\sigma}{\tau})
.\end{equation*}

\begin{equation}\label{eq:c_1_w}
\left(\begin{array}{c}
     -\mathcal{D}_f[\wtilde{x}_\theta]^T w(x,\wtilde x_\theta) \\
