\label{lem:shift_ang_general}
    Let $G_0$ be a $d$ dimensional linear space in $\mathbb{R}^D$, and let $g_0:G_0 \rightarrow \mathbb{R}^{D-d}$, such that the graph of $g_0$ is a manifold with reach bounded by $\tau$. Assume that $\angle_{\max} (T_0g_0, G_0) \leq \alpha$. Let  $G_1$ be a $d$ dimensional linear space in $\mathbb{R}^D$, such that $\angle_{\max}(G_0,G_1)\leq \beta$. Define $g_1:G_1 \rightarrow \mathbb{R}^{D-d}$ as the function who's graph coincides with the graph of $g_0$. 

    Then, for $\alpha \leq \pi/16$, $\beta\leq \beta_c$ where $\beta_c$ is some constant dependent only on $c_{\pi/4}$ of Lemma \ref{lem:M_is_locally_a_fuinction_clean}, and  $\|g_0(0)\| \leq \frac{3\tau}{4 \cdot 16} $, we have 
    \[
    \angle_{\max} (G_1, T_0g_1)) \leq \angle_{\max}(G_1, T_0g_0)  + \frac{ 8\|g_0(0)\|}{\tau}
    \]

We begin with defining the coordinate system $(\tilde o_1, G_1)$ with $\tilde o_1 = (0, g_0(0))_{G_0}$. Let $\wtilde g_1:(\wtilde o_1,G_1) \simeq \mathbb{R}^d \to \mathbb{R}^{D-d}$ be the function defined in Lemma \ref{lem:M_is_locally_a_fuinction_clean}, such that 
\[
\Gamma_{\wtilde g_1} =  \mathcal{M} \cap \textrm{Cyl}(\wtilde o_1,c_{\pi/4}\tau, \tau/2)
\]
From Lemma \ref{lem:M_is_locally_a_fuinction_clean} we know that $\wtilde g_1$ is defined for any $x\in \mathbb{R}^d$ such that $\norm{x} \leq c_{\pi/4}\tau$.
Now, we denote $x_o = P_{G_1}(o_1 - \tilde o_1)$, the projection of $o_1$ onto the affine space defined by $(\tilde o_1, G_1)$.
From the assumptions we know that $\norm {\tilde o_1 - o_1} \leq  \frac{3\tau}{4 \cdot 16}$. 
Since $\angle_{\max} (G_1,G_0) \leq \beta$ from Lemma \ref{lem:angle_space_to_vec} we have that $\norm{x_o} \leq \frac{3\tau}{4 \cdot 16} \sin \beta$. 
Thus, for sufficiently small $\beta$, depending only on $c_{\pi/4}$, $\|x_o\| \leq c_{\pi/4}
\tau$, and $\wtilde{g}_1(x_o)$ is therefore defined (by Lemma \ref{lem:M_is_locally_a_fuinction_clean}). Since $\wtilde g_1$ identifies with $g_1$ up to some shift in the domain and target, it follows that $g_1(0)$ is well defined.

Next we bound  $ \|P_{T_0g_0} (o_1 + (0, g_{1}(0))_{G_1} - \tilde o_1) \| $.
Since $\wtilde{g}_1(0) = 0$, from Lemma \ref{lem:f_bound_circle_H_clean} and the triangle inequality for maximal angles between flats
we have that 
\[
\|\wtilde{g}_1(x_o)\| \leq \tau\cos(\alpha + \beta)-\sqrt{\tau^2-(\norm{x_o} + \tau\sin(\alpha+\beta))^2}
\]
Substituting $\|x_o\|$ in the right hand side we set 
\begin{align}
\|\wtilde{g}_1(x_o)\| &\leq \tau\cos(\alpha + \beta)-\sqrt{\tau^2-(\frac{3\tau}{4 \cdot 16} \sin \beta + \tau\sin(\alpha+\beta))^2} \notag\\
&= \tau \left( \cos(\alpha + \beta)-\sqrt{1-(\frac{3}{4 \cdot 16} \sin \beta + \sin(\alpha+\beta))^2} \right)    
\end{align}
Since  
\begin{multline}
 \|P_{T_0g_0} (o_1 + (0, g_{1}(0))_{G_1} - \tilde o_1) \| \leq \norm{o_1 + (0, g_{1}(0))_{G_1} - \tilde o_1)}   = \sqrt{\|\wtilde{g}_1(x_o)\|^2 + \|x_o\|^2} 
\\
= \tau \sqrt{\left(\frac{3}{4 \cdot 16}\right)^2 \sin^2 \beta + \left( \cos(\alpha + \beta)-\sqrt{1-(\frac{3}{4 \cdot 16} \sin \beta + \sin(\alpha+\beta))^2} \right)^2 }
\end{multline}
which, for small enough $\beta$ and fixed $\alpha$ is smaller than $0.5 \tau$.
